KG42.register("edges-a3c805a0f8d8ac17b8a5a57d",{"id":"S-6deb0758a4c04807","source":"COMP-de3c29746c6c77cb","type":"links","target":"COMP-f4dbfe7382837244","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["05-double_auction"],"assertions":[{"id":"05-double_auction::v141-c-R018::E::v141-c-R018-E001","paper":"05-double_auction","rule_id":"v141-c-R018","rule_ref":"05-double_auction::v141-c-R018","record":{"edge_id":"v141-c-R018-E001","source":"coordination.local_operator","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R018-C002"],"evidence_ids":["v141-b-g01-ev-07"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R018-C002"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-de3c29746c6c77cb","target":"COMP-f4dbfe7382837244","source_occurrence_id":"05-double_auction::v141-c-R018::V::coordination.local_operator","target_occurrence_id":"05-double_auction::v141-c-R018::V::settlement.payment","source_unit_id":"05-double_auction::v141-a-M03::coordination.local_operator","target_unit_id":"05-double_auction::v141-a-M03::settlement.payment","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Financing the payment deficit in VCG transactions. | VCG payment rules reviewed for local P2P energy trading; buyer and seller rates are distinct.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-05","v141-b-g01-ev-07"]},"active":true,"source_signature":"8f156a1e5b76cf3cc151b45b05273468112e01e8875d839b99a4acb4535cb0b6","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M03","source_definition":"Information, allocation, governance or payment coordination in this mechanism: The paper reviews welfare/truthfulness and distinct buyer/seller price formulas; an operator subsidy may cover the transaction deficit.","target_definition":"Monetary obligations, transfers, sharing or settlement conditions in this mechanism: The paper reviews welfare/truthfulness and distinct buyer/seller price formulas; an operator subsidy may cover the transaction deficit.","constraints":[{"constraint_id":"v141-c-R018-C002","kind":"logical","role":"core","statement":"The market operator must subsidize the deficit between buyer payments and seller receipts to facilitate the transaction. Scope: Financing the payment deficit in VCG transactions. Condition: The price trading buyers pay is less than the price trading sellers receive.","expression":"\\text{deficit} = \\min(S_{\\gamma+1}^P,\\, B_{\\gamma}^P) - \\max(S^P,\\, B_{\\gamma+1}^P) > 0, \\quad \\text{subsidized by the market operator}","formalization_origin":"equivalent_translation","template_id":null,"members":["coordination.local_operator","settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R018-T01","v141-c-R018-T02","v141-c-R018-T03","v141-c-R018-T04"],"evidence_ids":["v141-b-g01-ev-07"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-07","location":{"location_id":"src-22913ad574-p03-c1r1__v141-a-M03-clearing","page":3,"printed_page":null,"section":"2.1","anchor_text":"J. Lin, et al. and S P are the bid and ask prices at the largest breakeven index, re- 2. spectively.","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Vickrey-Clark-Groves (VCG) mechanism is an alternative auction mechanism that maximizes social welfare and motivates participants to bid truthfully at the expense of the market operator [46]. $B_{\\gamma+1}^P$ and $S_{\\gamma+1}^P$ are the bid and ask prices following the largest breakeven index, respectively. Effectively, $B_{\\gamma}^P \\geq B_{\\gamma+1}^P$ and $S_{\\gamma}^P \\leq S_{\\gamma+1}^P$ due to the natural ordering rule for sorting offers. Since the price that trading buyers pay is less than the price that trading sellers receive, there exists a deficit that needs to be subsidized by the market operator to facilitate the transaction."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Financing the payment deficit in VCG transactions. | VCG payment rules reviewed for local P2P energy trading; buyer and seller rates are distinct.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-05","v141-b-g01-ev-07"]},"source_record":{"edge_id":"v141-c-R018-E001","source":"coordination.local_operator","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R018-C002"],"evidence_ids":["v141-b-g01-ev-07"]},"paper_scope_note":"The four auctions are kept separate; the time-period conditions of marginal index, buy/sell eligibility, price bound, shortfall subsidy, and historical price are retained. What is cited is the mechanism description given in the paper and is not expanded to all VCG definitions."}}],"assertion_ids":["05-double_auction::v141-c-R018::E::v141-c-R018-E001"]});
